def lab():
    """Lab page with the vulnerable login form"""
    import sqlite3
    from flask import request, render_template
    if request.method == "POST":
        username = request.form.get("username", "")
        password = request.form.get("password", "")

        sql_query = "SELECT * FROM users WHERE username=? AND password=?"

        try:
            conn = sqlite3.connect("database.db")
            c = conn.cursor()
            result = c.execute(sql_query, (username, password)).fetchone()
            conn.close()

            if result:
                return render_template("lab.html", logged_in_user=result[0])
            else:
                return render_template(
                    "lab.html",
                    error="Invalid username or password",
                    sql_query=sql_query,
                )
        except sqlite3.Error as e:
            return render_template("lab.html", error=str(e), sql_query=sql_query)

    return render_template("lab.html")
